import * as React from "react";
import { fireEvent, render, screen } from "@testing-library/react";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import * as stories from "./Header.stories";
import Header from "./Header";

const { Full } = composeStories(stories) as any;

describe("Header component", () => {
  it("pass A11Y", async () => {
    const { container } = render(<Full />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("can display a menu button", () => {
    const onMenuButtonClick = jest.fn();
    render(
      <Header
        appName="App Name"
        showMenuButton
        onMenuButtonClick={onMenuButtonClick}
      />
    );
    const menuButton = screen.getByLabelText("Open the menu");
    expect(menuButton).toBeDefined();
    fireEvent.click(menuButton);
    expect(onMenuButtonClick).toHaveBeenCalledTimes(1);
  });

  it("passes through props", () => {
    render(<Header appName="App Name" data-testid="header" />);
    expect(screen.getByTestId("header")).toBeTruthy();
  });
});
